import{_ as a,o,c as r,ai as i}from"./chunks/framework.Ba-VnP44.js";const p=JSON.parse('{"title":"费曼式输出与实践复盘","description":"","frontmatter":{},"headers":[],"relativePath":"ai/cognition/learn-by-doing.md","filePath":"ai/cognition/learn-by-doing.md"}'),e={name:"ai/cognition/learn-by-doing.md"};function n(l,t,d,s,h,g){return o(),r("div",null,[...t[0]||(t[0]=[i('<h1 id="费曼式输出与实践复盘" tabindex="-1">费曼式输出与实践复盘 <a class="header-anchor" href="#费曼式输出与实践复盘" aria-label="Permalink to “费曼式输出与实践复盘”">​</a></h1><p>学过不等于会用，会用不等于能复用。这一篇讲怎么通过输出和复盘，把零散的实践经验沉淀成真正属于你的、可迁移的能力。</p><h2 id="为什么关注" tabindex="-1">为什么关注 <a class="header-anchor" href="#为什么关注" aria-label="Permalink to “为什么关注”">​</a></h2><p>用 AI 做过不少事的人，往往有个共同的尴尬：去年解决过的问题，今年又踩了一遍坑；当时明明想出了很好的提示词写法，现在死活想不起来；面试或者给别人讲的时候，发现自己说不清&quot;我到底是怎么做到的&quot;。</p><p>问题出在输入和执行太多、整理太少。大脑对&quot;看过&quot;的东西会自动标记为已掌握，这正是错觉的来源。而费曼式输出——<strong>试着把一个东西讲给别人听</strong>——是最诚实的检测手段：讲不清的地方，就是没懂的地方，屡试不爽。</p><p>输出还有第二个作用：倒逼输入。当你决定写一篇&quot;我是怎么用 AI 把部署时间从两小时压到二十分钟&quot;的文章时，你会被迫去搞清楚每个环节的因果，而不是停留在&quot;反正跑通了&quot;。这个过程产生的理解深度，看十篇教程都换不来。</p><p>对工程师来说，输出的形态可以很轻：一条团队 wiki、一段十分钟的分享、一个能跑的示例仓库。不需要写爆款文章。</p><h2 id="方法与要点" tabindex="-1">方法与要点 <a class="header-anchor" href="#方法与要点" aria-label="Permalink to “方法与要点”">​</a></h2><h3 id="一、输出倒逼输入-写之前先问三个问题" tabindex="-1">一、输出倒逼输入：写之前先问三个问题 <a class="header-anchor" href="#一、输出倒逼输入-写之前先问三个问题" aria-label="Permalink to “一、输出倒逼输入：写之前先问三个问题”">​</a></h3><p>任何输出动笔前，先回答：</p><ol><li><strong>我到底解决了什么问题？</strong>（一句话说清场景和痛点）</li><li><strong>我是怎么解决的？</strong>（步骤、关键决策、为什么这么选而不是那么选）</li><li><strong>别人照着做，最容易在哪里卡住？</strong>（坑和前提条件）</li></ol><p>答不出来的地方，就是你还含糊的地方，也正是需要回去补的地方。写完这三个问题的答案，一篇文章的骨架就有了，而你的理解已经被迫加深了一层。</p><h3 id="二、输出的三种形态-按成本排序" tabindex="-1">二、输出的三种形态，按成本排序 <a class="header-anchor" href="#二、输出的三种形态-按成本排序" aria-label="Permalink to “二、输出的三种形态，按成本排序”">​</a></h3><table tabindex="0"><thead><tr><th>形态</th><th>成本</th><th>适用场景</th><th>沉淀效果</th></tr></thead><tbody><tr><td>笔记/踩坑记录</td><td>5 分钟</td><td>当天的发现、报错解法、好用的提示词</td><td>高（检索快，密度高）</td></tr><tr><td>文章/教程</td><td>1~3 小时</td><td>一个完整方法、一次有普适性的实践</td><td>最高（结构化，可传播）</td></tr><tr><td>分享/口述</td><td>30 分钟</td><td>团队内部、学习小组</td><td>中高（暴露表达层面的漏洞）</td></tr></tbody></table><p>原则：<strong>低成本的高频写，高成本的按项目写。</strong> 每次实践完花五分钟记三条，比攒半年写一篇大部头容易坚持，总产出也更高。文章留给&quot;这个方法值得反复用&quot;的主题。</p><p>费曼技巧的落点在这里：写教程时假设读者是&quot;一年前的自己&quot;——不许用行话糊弄，不许跳步骤。讲不明白的定义，说明你只是记住了名词。</p><h3 id="三、复盘模板-每次实践后-10-分钟" tabindex="-1">三、复盘模板：每次实践后 10 分钟 <a class="header-anchor" href="#三、复盘模板-每次实践后-10-分钟" aria-label="Permalink to “三、复盘模板：每次实践后 10 分钟”">​</a></h3><p>一个够用的模板，四行就够：</p><ol><li><strong>目标 vs 结果</strong>：本来想做什么？实际做成了什么？差在哪？</li><li><strong>关键决策</strong>：当时做了哪几个选择（用什么工具、怎么提示、哪里人工介入）？现在看对不对？</li><li><strong>意外发现</strong>：有没有超出预期的效果或坑？这类信息最有价值，因为不在任何教程里。</li><li><strong>下次怎么用</strong>：如果再遇到同类任务，我的标准动作是什么？——必须写成一句可执行的话，比如&quot;日志分析一律先让 AI 按时间线归类，再逐段追问&quot;，而不是&quot;多用 AI 分析日志&quot;这种正确的废话。</li></ol><p>第 4 条是复盘的灵魂。没有&quot;下次怎么用&quot;，复盘只是感想；有了它，每次实践都在往你的方法库里添一条可复用的规则。</p><h3 id="四、把实践变成可复用经验" tabindex="-1">四、把实践变成可复用经验 <a class="header-anchor" href="#四、把实践变成可复用经验" aria-label="Permalink to “四、把实践变成可复用经验”">​</a></h3><p>单次经验要变成资产，需要三步：</p><ol><li><strong>记录</strong>：模板化地记下来（上面四行）。</li><li><strong>归档</strong>：放进固定的地方，用固定标签（比如 <code>ai-实践/提示词</code>、<code>ai-实践/代码助手</code>、<code>ai-实践/文档处理</code>），能搜到才算存在。</li><li><strong>提炼</strong>：同类记录攒到 3~5 条时，合并成一篇方法总结——&quot;我处理 X 类问题的标准流程&quot;。这一步是从&quot;经历&quot;到&quot;经验&quot;的质变，也是你区别于&quot;用过 AI 的人&quot;的地方。</li></ol><p>隔一段时间回头读自己的方法总结，会发现有些已经过时了。更新它，就是在给自己的认知做版本管理。</p><h2 id="实践建议" tabindex="-1">实践建议 <a class="header-anchor" href="#实践建议" aria-label="Permalink to “实践建议”">​</a></h2><ol><li><strong>当天记</strong>：实践结束当天写三条记录，隔天细节就没了。五分钟，不要多。</li><li><strong>固定输出节奏</strong>：比如每两周一篇短文或一次小组分享。有节奏比有灵感可靠。</li><li><strong>先给最小读者</strong>：发到团队 wiki、学习群，哪怕只有三个人看。有真实读者的输出，质量提升远快于自言自语。</li><li><strong>建自己的方法库</strong>：一个仓库、一个笔记库都行，只要能搜、能加标签、能长期活着。</li><li><strong>旧文重读</strong>：每季度翻一次三个月前的记录，把过时的改掉、能提炼的提炼。复盘复盘，也包括复盘你的复盘。</li></ol><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to “小结”">​</a></h2><p>输入让人安心，输出才让人成长。费曼式输出的价值在于：讲不清的地方暴露了没懂的地方，写教程的过程强制你理清因果；而一套&quot;目标—决策—发现—下次动作&quot;的复盘模板，能把每次实践从一次性经历变成可检索、可复用、可迭代的经验资产。做了不总结，等于没做；总结不输出，理解停在半空。认知成长的加速度，来自输出的频率。</p>',28)])])}const u=a(e,[["render",n]]);export{p as __pageData,u as default};
